for name in ["drill", "flashlight", "pliers", "screwdriver", "allen wrench"]:
    res = primitives.call(
        name="submit_capx_action",
        action="get_object_pose",
        native_api=True,
        parameters={"object_name": name, "return_bbox_extent": True},
    )
    if res.ok and res.output.get("native_api_result"):
        r = res.output["native_api_result"]
        if r[0] is not None:
            print(name, "pos:", r[0]["values"], "ext:", r[2]["values"])
        else:
            print(name, "-> None")
